import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import 'auth_providers.dart';
class OtpScreen extends ConsumerStatefulWidget{const OtpScreen({super.key,required this.phone});final String phone;@override ConsumerState<OtpScreen>createState()=>_OtpState();}class _OtpState extends ConsumerState<OtpScreen>{final otp=TextEditingController();String? error;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Verify phone')),body:Padding(padding:const EdgeInsets.all(24),child:Column(children:[TextField(controller:otp,keyboardType:TextInputType.number,maxLength:6,decoration:const InputDecoration(labelText:'OTP')),if(error!=null)Text(error!),FilledButton(onPressed:()async{if(otp.text.length!=6){setState(()=>error='OTP must be 6 digits');return;}try{await ref.read(authSessionProvider.notifier).verify(widget.phone,otp.text);if(mounted)context.go('/home');}catch(e){setState(()=>error=e.toString());}},child:const Text('Verify'))])));}
